// A published plugin gets the HTTP request; a start through the API, its headers.
string requestId;
if (WorkflowEnvironment.Variables.TryGetValue("HttpRequest", out object raw)
    && raw is Microsoft.AspNetCore.Http.HttpRequest http)
    requestId = http.Headers["x-ms-client-request-id"].ToString();
else
    requestId = ServiceProvider.GetService<HttpRequestService>()?.Request?.Headers?
        .FirstOrDefault(h => string.Equals(h.Key, "x-ms-client-request-id", StringComparison.OrdinalIgnoreCase)).Value;
if (string.IsNullOrEmpty(requestId))
    throw new Exception("x-ms-client-request-id is required");
Parameters.cacheKey = $"payment:{requestId}";
return requestId;

// The platform's distributed cache: shared by every instance of every Flow
// of the stand, so a retry finds the answer whichever instance served it.
var cache = ServiceProvider.GetService<IDistributedCache>();
return cache?.GetString(Parameters.cacheKey);     // null: not answered yet

// The stored answer, unchanged: a client that lost the response can retry safely.
var answer = JsonConvert.DeserializeObject<PaymentAnswer>((string)#Previous);
answer.cacheStatus = "IsCompleted";
if (WorkflowEnvironment.Variables.TryGetValue("HttpResponse", out object raw)
    && raw is Microsoft.AspNetCore.Http.HttpResponse response)
    response.Headers["cacheStatus"] = answer.cacheStatus;
return answer;

// The work itself, done once per request id: here it only issues a
// confirmation, so a repeated call is easy to recognise.
return new PaymentAnswer()
{
    orderId = Input.orderId,
    amount = Input.amount,
    confirmation = Guid.NewGuid().ToString(),
    acceptedAt = DateTime.UtcNow.ToString("o"),
    cacheStatus = "Added"
};

// Stored for cacheSeconds from the configuration Flow; after that the same
// request id is a new request.
var answer = (PaymentAnswer)#Previous;
ServiceProvider.GetService<IDistributedCache>()?.SetString(Parameters.cacheKey,
    JsonConvert.SerializeObject(answer),
    new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(Parameters.config.cacheSeconds) });
if (WorkflowEnvironment.Variables.TryGetValue("HttpResponse", out object raw)
    && raw is Microsoft.AspNetCore.Http.HttpResponse response)
    response.Headers["cacheStatus"] = answer.cacheStatus;
return answer;

types.PaymentAnswer:
public class PaymentAnswer
{
    public string orderId { get; set; }
    public double amount { get; set; }
    /* Issued once per request id: a repeated call gets the same value. */
    public string confirmation { get; set; }
    public string acceptedAt { get; set; }
    /* Added - answered now and stored; IsCompleted - answered from the cache. */
    public string cacheStatus { get; set; }
}
